import math

def is_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

# We are looking for x^5 + x = 2^k + 2, or 2^k = x^5 + x - 2
# Constraints: x > 5 (since n=5)

print("Searching for solutions for n=5, x > 5.")
solutions = []

# Search x up to 20 based on prior manual checks, prioritizing candidates satisfying x = 1, 5 (mod 8)
# Candidates: 9, 13, 17, 21 (if we go slightly further), 25, ...
x_candidates = [9, 13, 17] 
# Let's extend to 33 to test the residue classes thoroughly
x_candidates.extend([25, 33])


for x in x_candidates:
    LHS = x**5 + x - 2

    if LHS <= 0:
        continue

    if is_power_of_two(LHS):
        k = LHS.bit_length() - 1
        print(f"Potential solution found: (x={x}, n=5, k={k})")
        solutions.append((x, 5, k))
    else:
        print(f"x={x}: LHS={LHS} is not a power of two.")

if not solutions:
    print("\nNo solutions found in the tested range.")

def is_power_of_two(n):
    return n > 0 and (n & (n - 1) == 0)

solutions = []
for x in range(4, 51):
    target = x**3 + x - 2
    if is_power_of_two(target):
        k = target.bit_length() - 1
        solutions.append((x, k))

print("Solutions for n=3 (x>3):", solutions)

import math

def check_power_of_two(V):
    if V <= 0:
        return False
    return (V & (V - 1)) == 0

print("--- Testing Candidate B: Check n=7 solutions ---")
solutions_found = []

N = 7
X_START = N + 1 # x must be > 7
X_LIMIT = 15

for x in range(X_START, X_LIMIT + 1):
    # Calculate V = x^7 + x - 2
    try:
        V = x**N + x - 2
    except OverflowError:
        print(f"Value exceeded standard integer limits for x={x}")
        break

    if check_power_of_two(V):
        # Found a solution
        k = int(math.log2(V))
        solutions_found.append((x, N, k))
        print(f"Solution found for n={N}: (x={x}, k={k}) where x^7 + x - 2 = 2^k")

if not solutions_found:
    print("No solutions found for n=7 in the search range.")
else:
    print("Solutions found for n=7:")
    for sol in solutions_found:
        print(sol)

print("--- End of search ---")
